_TABLE = None


def _load():
    global _TABLE
    if _TABLE is None:
        raw = zlib.decompress(base64.b85decode(_PACKED.encode("ascii")))
        _TABLE = json.loads(raw.decode("utf-8"))
    return _TABLE


def lookup(country_code: str, city_key: str) -> Optional[float]:
    """Return the altitude in metres for a normalized city key, or ``None``."""
    value = _load().get(f"{(country_code or '').upper()}|{city_key}")
    return None if value is None else float(value)


def city_count() -> int:
    """Number of cities in the generated map."""
    return len(_load())
